import React, { useState } from 'react';
import './App.css';

function App() {
  const [menu, setMenu] = useState({
    'Petit Déjeuner': [
      { name: 'Croissant', price: 1.5, selected: false },
      { name: 'Café', price: 2.0, selected: false },
      { name: 'Tartine Beurre', price: 1.2, selected: false },
    ],
    'Chicha': [
      { name: 'Double Pomme', price: 10, selected: false },
      { name: 'Menthe', price: 10, selected: false },
      { name: 'Raisin', price: 10, selected: false },
    ],
    'Boissons': [
      { name: 'Thé', price: 2, selected: false },
      { name: 'Jus d\'orange', price: 3.5, selected: false },
    ]
  });

  const toggleItem = (category, index) => {
    const updatedCategory = [...menu[category]];
    updatedCategory[index].selected = !updatedCategory[index].selected;
    setMenu({ ...menu, [category]: updatedCategory });
  };

  const accept = () => {
    let selectedItems = [];
    Object.keys(menu).forEach(category => {
      selectedItems = selectedItems.concat(
        menu[category].filter(item => item.selected).map(item => `${item.name} (${category})`)
      );
    });
    alert("Vous avez choisi :\n" + selectedItems.join(', '));
  };

  const callWaiter = () => {
    alert("Le serveur arrive !");
  };

  return (
    <div className="App">
      <h1>🍽️ Menu du Café</h1>

      {Object.keys(menu).map(category => (
        <div key={category}>
          <h2>{category}</h2>
          <ul>
            {menu[category].map((item, idx) => (
              <li key={idx}>
                <label>
                  <input
                    type="checkbox"
                    checked={item.selected}
                    onChange={() => toggleItem(category, idx)}
                  />
                  {item.name} - {item.price} €
                </label>
              </li>
            ))}
          </ul>
        </div>
      ))}

      <button onClick={accept}>✅ Accepter</button>
      <button onClick={callWaiter}>🔔 Appeler le serveur</button>
    </div>
  );
}

export default App;
